class ConnectionPool:
    def __init__(self, factory, maxsize=10):
        self._factory = factory
        self._maxsize = maxsize
        self._lock = threading.Lock()
        self._idle = collections.deque()
        self._in_use = 0
    def acquire(self, timeout=5):
        deadline = time.time() + timeout
        while True:
            with self._lock:
                if self._idle:
                    return self._idle.popleft()
                if self._in_use < self._maxsize:
                    self._in_use += 1
                    return self._factory()
            if time.time() > deadline:
                raise TimeoutError('pool exhausted')
            time.sleep(0.01)
    def release(self, conn):
        with self._lock:
            self._in_use -= 1
            self._idle.append(conn)

async function fetchWithRetry(url: string, opts: {retries?: number; backoffMs?: number; timeoutMs?: number} = {}): Promise<Response> {
  const {retries = 3, backoffMs = 200, timeoutMs = 8000} = opts;
  let attempt = 0;
  for (;;) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
      const res = await fetch(url, {signal: ctrl.signal});
      if (res.ok || res.status < 500 || attempt >= retries) return res;
    } catch (err) {
      if (attempt >= retries) throw err;
    } finally {
      clearTimeout(timer);
    }
    await new Promise(r => setTimeout(r, backoffMs * 2 ** attempt + Math.random() * 100));
    attempt += 1;
  }
}

func (t *Tracker) Record(chainID string, tokens int64) (kill bool, reason string) {
	if chainID == "" {
		return false, ""
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	now := t.now()
	st, ok := t.chains[chainID]
	if !ok || now.Sub(st.firstSeen) >= t.limits.Window {
		st = &chainState{firstSeen: now}
		t.chains[chainID] = st
	}
	st.depth++
	st.tokens += tokens
	return false, ""
}
